#pragma once
// Plain data that describes every IMMINENCE plugin. The tables are generated by tools/gen/generate.py
// from the browser preview, so the preview and the plugins always share the same shaders and controls.

enum ImParamKind
{
	IM_SLIDER = 0,// 0..1 slider, sent to the shader as is
	IM_OPTION = 1,// dropdown, each choice sends its own value to the shader
	IM_TOGGLE = 2 // on/off, sends 0 or 1
};

struct ImParamDef
{
	const char* label;        // what the user sees in Arena
	int slot;                 // which shader uniform (uP0..uP7) receives the value
	ImParamKind kind;
	float defaultValue;       // slider/toggle: value. option: index of the default choice
	int numOptions;
	const char* const* optionLabels;
	const float* optionValues;// value sent to the shader for each choice
};

enum ImStyleFlags
{
	IM_FEEDBACK = 1 << 0,// reads its own previous frame (uPrev)
	IM_HISTORY  = 1 << 1,// reads the 48 frame history buffer (uHist)
	IM_TEXT     = 1 << 2,// reads the word texture (uText)
	IM_GLYPH    = 1 << 3,// reads the ASCII glyph atlas (uGlyph)
	IM_SECOND   = 1 << 4 // reads a second input (transitions)
};

struct ImStyleDef
{
	const char* label;
	const char* description;
	const char* const* source;// fragment shader body, split in chunks, nullptr terminated
	const ImParamDef* params;
	int numParams;
	unsigned flags;
};

enum ImKind
{
	IM_KIND_EFFECT = 0,
	IM_KIND_SOURCE = 1,
	IM_KIND_MIXER  = 2
};

struct ImFamilyDef
{
	const char* id;  // 4 character FFGL id
	const char* name;// shown in Arena, max 16 characters
	const char* description;
	ImKind kind;
	const ImStyleDef* styles;
	int numStyles;
};
